import java.util.*;class TaskBinding{static Object graph(int n){return new alternate.Graph(n);}static void add(Object g,int a,int b){((alternate.Graph)g).add(a,b);}static void remove(Object g,int a,int b){((alternate.Graph)g).remove(a,b);}static boolean edge(Object g,int a,int b){return ((alternate.Graph)g).edge(a,b);}static Set<Integer>neighbors(Object g,int v){return ((alternate.Graph)g).neighbors(v);}}
